const state = $('Search State').itemMatching(0).json;
const track = state.track;
const responses = $input.all().map(item => item.json);

/** Normalize file text for matching. @param {unknown} value Text to normalize. @returns {string} Comparable text. */
function norm(value) {
  return String(value ?? '').normalize('NFKD').toLowerCase()
    .replace(/[\\/_()[\].-]+/g, ' ').replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ').trim();
}

const artist = norm(track.primaryArtist);
const title = norm(track.title);
const versions = ['karaoke', 'instrumental', 'tribute', 'cover', 'live', 'remix', 'bootleg', 'mashup', 'transition', 'edit', 'rework', 'vip', 'acoustic', 'nightcore', 'sped up', 'slowed'];
const candidates = responses.flatMap(peer => (peer.files ?? []).flatMap(file => {
  const filename = String(file.filename ?? '');
  const name = norm(filename.split(/[\\/]/).pop());
  const path = norm(filename);
  const ext = filename.split('.').pop()?.toLowerCase();
  if (file.isLocked || !['flac', 'mp3', 'm4a', 'aac', 'ogg', 'wav', 'aiff'].includes(ext) || !Number.isFinite(Number(file.size)) || Number(file.size) < 100000) return [];
  const artistMatch = Boolean(artist) && path.includes(artist);
  const titleMatch = Boolean(title) && name.includes(title);
  const length = Number(file.length);
  const durationDifference = Number.isFinite(length) && length > 0 ? Math.abs(length - Number(track.durationSeconds)) : null;
  const unwanted = versions.filter(word => name.includes(word) && !title.includes(word));
  let score = (artistMatch ? 45 : 0) + (titleMatch ? 65 : 0) + (artistMatch && titleMatch ? 35 : 0);
  if (durationDifference !== null) score += durationDifference <= 2 ? 60 : durationDifference <= 4 ? 40 : durationDifference <= 7 ? 20 : durationDifference <= 15 ? -30 : -80;
  score -= unwanted.length * 60;
  score += ext === 'flac' ? 12 : ext === 'mp3' ? 8 : 0;
  const rate = Number(file.bitRate);
  if (ext === 'mp3' && Number.isFinite(rate)) score += rate >= 320 && rate <= 500 ? 6 : rate >= 256 ? 4 : rate >= 192 ? 2 : rate > 0 && rate < 128 ? -5 : 0;
  if (peer.hasFreeUploadSlot) score += 3;
  if (Number(peer.queueLength) === 0) score += 2;
  return [{ score, artistMatch, titleMatch, unwanted, durationDifference,
    spotifyId: track.spotifyId, spotifyTitle: track.title, spotifyArtist: track.artist,
    spotifyDuration: track.durationSeconds, spotifyUrl: track.spotifyUrl,
    searchId: state.searchId, username: peer.username, filename, size: file.size,
    bitRate: file.bitRate, length: file.length, hasFreeUploadSlot: peer.hasFreeUploadSlot,
    queueLength: peer.queueLength, uploadSpeed: peer.uploadSpeed }];
}));

candidates.sort((a, b) => b.score - a.score);
const best = candidates[0];
const next = candidates[1];
const fallbackCandidate = candidates.find(candidate => candidate.username !== best?.username && candidate.artistMatch && candidate.titleMatch && candidate.durationDifference !== null && candidate.durationDifference <= 4 && candidate.unwanted.length === 0 && candidate.score >= 175) ?? null;
const fastFallbackCandidate = candidates.find(candidate => candidate.username !== best?.username && candidate.artistMatch && candidate.titleMatch && candidate.durationDifference !== null && candidate.durationDifference <= 4 && candidate.unwanted.length === 0 && candidate.score >= 175 && candidate.hasFreeUploadSlot === true && Number(candidate.queueLength) === 0) ?? null;
const margin = best && next ? best.score - next.score : null;
const exact = best?.artistMatch && best?.titleMatch && best?.durationDifference !== null && best.durationDifference <= 4 && best.unwanted.length === 0;
const rival = next && margin < 8 && (!next.artistMatch || !next.titleMatch || next.durationDifference === null || next.durationDifference > 7 || next.unwanted.length > 0);
const status = !best ? 'no_match' : exact && best.score >= 175 && !rival ? 'AUTO_DOWNLOAD' : 'review';
return [{ json: { ...best, status, reason: !best ? 'No playable unlocked files' : status === 'review' ? 'Low confidence or competing version' : 'High confidence', margin,
